async def _evaluation_sync(enabled, operation, /, *args, **kwargs):
    """Keep evaluate CPU projections off the loop without detached mutations."""
    if not enabled:
        return operation(*args, **kwargs)
    worker = asyncio.create_task(asyncio.to_thread(operation, *args, **kwargs))
    try:
        return await asyncio.shield(worker)
    except asyncio.CancelledError:
        while not worker.done():
            try:
                await asyncio.shield(worker)
            except asyncio.CancelledError:
                continue
            except Exception:
                break
        if worker.done() and not worker.cancelled():
            worker.exception()
        raise


def _evaluation_citation_identity_facts(facts):
    """Finite same-species aliases in a citation-only view; source DTOs stay whole.

    NLM MeSH D016360 lists Clostridium difficile as the entry term for
    Clostridioides difficile: https://meshb.nlm.nih.gov/record/ui?ui=D016360
    No genus, strain, measured value or source detection is inferred.
    """
    result = dict(facts)
    names = ('Clostridioides difficile', 'Clostridium difficile')
    for fid, fact in facts.items():
        aliases = [name.strip() for name in fact.name.split(' / ')]
        if fact.kind != 'microbe' or not any(name.casefold() in {item.casefold() for item in names} for name in aliases):
            continue
        missing = [name for name in names if name.casefold() not in {alias.casefold() for alias in aliases}]
        if missing:
            result[fid] = fact.model_copy(update={'name': fact.name + ' / ' + ' / '.join(missing)})
    return result


def _mentioned_microbe_ids(text, facts):
    return _clinical_mentioned_microbe_ids(text, _evaluation_citation_identity_facts(facts))


