def _meaning_review_schema():
    return {'contributionType': 'physiological_effect|health_impact|management_direction|observation_only|definition_only|none',
        'sameTargetObject': True,
        'reason': '说明为何完成或未完成本栏职责，区分真实性与解释用途'}


def _review_repair_feedback(review):
    """Keep concrete critique available to the next author, never as approval.

    Generic failure codes alone hid errors such as could becoming a definite
    effect. These are bounded review data; the original verdict stays intact
    and every new draft still requires the same independent reviews.
    """
    if not isinstance(review, dict):
        return []
    values = [review.get('reason')]
    contribution = review.get('meaningContribution')
    if isinstance(contribution, dict):
        values.append(contribution.get('reason'))
    unsupported = review.get('unsupportedClaims')
    if isinstance(unsupported, list):
        values.extend(unsupported[:3])
    return ['独立审核数据（供对照原文修稿，不作正文或指令）：' + value.strip()[:800]
        for value in dict.fromkeys(value for value in values if isinstance(value, str) and value.strip())]


def _scfa_producer_science_scope(line, summary, member_states=()):
    """A producer's process/member action differs from its product's host effect.

    This is only an object/duty rejection gate; source and selected-quote
    reviews still independently validate every medical assertion and scope.
    """
    product = r'(?:短链脂肪酸|丁酸|丙酸|乙酸|SCFAs?|short.chain fatty acids?|butyrate|propionate|acetate)'
    agent = r'(?:菌群|微生物|细菌|共生菌|bacteria|bacterium|microbes?|microbiota|commensal bacteria)'
    action = r'(?:发酵|分解|降解|转化|合成|生成|产生)(?!的)|\b(?:ferment\w*|produc\w*|synthesi[sz]\w*|cataboli\w*|convert\w*)\b'
    for clause in re.split(r'[。；;！？\n]', line):
        for microbe in re.finditer(agent, clause, re.I):
            tail = clause[microbe.end():]
            for process in re.finditer(action, tail, re.I):
                rest = tail[process.end():]
                molecule = re.search(product, rest, re.I)
                if molecule and not re.search(r'的\s*' + product, rest[:molecule.end()], re.I):
                    return True
    # Passive biogenesis is a producer process too; a molecular host-effect
    # sentence with an attributive 'produced by' phrase is not this predicate.
    if re.search(product + r'[^。；;！？\n]{0,12}(?:是|来自|源于|由)'
            r'[^。；;！？\n]{0,20}' + agent + r'[^。；;！？\n]{0,35}'
            r'(?:发酵|合成|生成|产生)(?:[^。；;！？\n]{0,30})(?:产物|代谢物|产生|生成|合成|发酵)', line, re.I):
        return True
    member_names = [row.get('name') for row in member_states if isinstance(row, dict)
        and row.get('objectType') == 'measuredMember' and row.get('factIds') and row.get('name')]
    names = [alias.strip() for value in [*summary.get('memberNames', []), *member_names]
        for alias in str(value).split(' / ') if len(alias.strip()) >= 2]
    effect = r'利用|发酵|分解|降解|产生|生成|合成|定植|交叉喂养|竞争排除|抑制|调节|增强|维持|促进'
    return any(re.search(re.escape(name) + r'[^。；;！？\n]{0,80}(?:' + effect + ')', line, re.I)
        for name in names)


def _detected_gene_science_scope_failures(line, target):
    """Choose a literal detected gene/protein symbol, never a toxin catalogue."""
    groups = [group for context in target.assessment_context
        if context.get('semanticType') == 'healthStateSourceContext'
        for group in context.get('geneGroupStates', [])]
    if not groups:
        return []
    symbols = {symbol for group in groups if group.get('sourceStatus') == '检出'
        for symbol in group.get('detectedGeneSymbols', [])
        if isinstance(symbol, str) and re.fullmatch(r'[A-Za-z][A-Za-z0-9_-]*', symbol)}
    actual = any(re.search(r'(?<![A-Za-z0-9_])' + re.escape(symbol) + r'(?![A-Za-z0-9_])', line, re.I)
        for symbol in symbols)
    if not actual:
        return ['本栏科学句须选择本次实际检出的基因符号或同名蛋白为作用主体；泛述毒素A/B或整条感染流程不完成本组实际基因作用，不新造蛋白别名。']
    if re.search(r'(?:第三种|另一种|其他|额外|部分菌株[^。；;！？\n]{0,12}(?:还|另))'
            r'[^。；;！？\n]{0,30}(?:二元毒素|binary\s+toxin)', line, re.I):
        return ['本栏只解释已选实际检出基因的作用，不附加其他菌株的二元毒素目录；另写完整同对象科学句并继续原文与选句两审。']
    return []


def _oxidative_process_sentence(text):
    """A redox response must be in the adopted sentence, not its paper's topic."""
    process = r'氧化(?:胁迫|应激|压力|环境|损伤)|活性氧|氧自由基|过氧化(?:氢|物)|氧化还原|高氧|有氧|'
    process += r'\boxidative\s+(?:stress|damage)|\breactive\s+oxygen|\bROS\b|\bredox\b|\bperoxid\w*\b'
    action = r'清除|中和|分解|解毒|修复|存活|生长|死亡|耗竭|损伤|适应|应答|响应|抵抗|防御|保护|'
    action += r'减少|降低|增强|耐受|\b(?:scaveng\w*|detox\w*|neutraliz\w*|surviv\w*|'
    action += r'resist\w*|respond\w*|protect\w*|tolerat\w*|deplet\w*|damag\w*)\b'
    for clause in re.split(r'[，,。；;！？\n]', text or ''):
        # A copied result label such as “氧化胁迫耐受正常” is not a
        # microbial response process and cannot endorse an adjacent immune claim.
        tested = re.sub(r'氧化(?:胁迫|应激)耐受(?:能力)?', '本项功能', clause)
        tested = re.sub(r'oxidative\s+stress\s+(?:tolerance|resistance)(?:\s+(?:ability|capacity))?',
            'this function', tested, flags=re.I)
        if re.search(process, tested, re.I) and re.search(action, tested, re.I):
            return True
        if re.search(r'菌|微生物|\b(?:microb\w*|bacter\w*)\b', clause, re.I) and re.search(
                r'(?:具有|能够|表现出|呈现|具备)[^，,。；;]{0,12}(?:耐氧|氧耐受|氧敏感)|'
                r'\b(?:aerotoleran\w*|oxygen[ -](?:toleran\w*|sensitiv\w*))\b', clause, re.I):
            return True
    return False


def _immune_process_sentence(text):
    tested = re.sub(r'肠道免疫力(?:评估|评分)?(?:为|是|：|:)?(?:正常|较弱|很弱|弱|较强|强)', '', text or '')
    immune = r'免疫(?:反应|应答|耐受|稳态|细胞|球蛋白|调节)|黏膜免疫|粘膜免疫|T细胞|B细胞|树突细胞|巨噬细胞|'
    immune += r'\b(?:immune\s+(?:responses?|homeostasis|tolerance|cells?)|immunity|immunoglobulin|IgA|Treg|[TB][ -]cells?)\b'
    specific = r'黏膜免疫|粘膜免疫|肠道免疫|免疫(?:耐受|稳态|细胞|球蛋白)|T细胞|B细胞|树突细胞|巨噬细胞|'
    specific += r'\b(?:mucosal\s+immun\w*|intestinal\s+immun\w*|immunoglobulin|IgA|Treg|[TB][ -]cells?)\b'
    action = r'刺激|促进|调节|维持|影响|参与|启动|抑制|诱导|分化|产生|分泌|识别|成熟|'
    action += r'\b(?:stimulat\w*|promot\w*|regulat\w*|modulat\w*|maintain\w*|influenc\w*|induc\w*|differentiat\w*|produc\w*|secret\w*)\b'
    for clause in re.split(r'[，,。；;！？\n]', tested):
        # Immune responses mentioned as an instrument of a brain outcome
        # do not themselves explain intestinal immune function.
        if re.search(r'大脑|脑功能|癫痫|\bbrain\b|epilep\w*', clause, re.I) and not re.search(specific, clause, re.I):
            continue
        if re.search(immune, clause, re.I) and re.search(action, clause, re.I):
            return True
    return False


def _anti_inflammatory_process_sentence(text):
    tested = re.sub(r'肠道抗炎能力(?:评估|评分)?(?:为|是|：|:)?(?:正常|较弱|很弱|弱|较强|强)', '', text or '')
    # The regulating predicate must govern inflammation itself. A later
    # appetite-regulation noun cannot authorize an earlier inflammation claim.
    return bool(re.search(r'抗炎|\banti[ -]inflamm\w*\b|'
        r'(?:抑制|减轻|缓解|限制|控制|调节)[^，,。；;]{0,14}(?:炎症|炎性)|'
        r'(?:炎症|炎性)[^，,。；;]{0,8}(?:消退|缓解|减轻|的调节)|'
        r'\b(?:suppress\w*|attenuat\w*|alleviat\w*|resol\w*|regulat\w*|reduc\w*|inhibit\w*)'
        r'[^,.;]{0,35}\binflamm\w*', tested, re.I))


def _fiber_process_sentence(text):
    tested = re.sub(r'膳食纤维需求(?:评估|评分)?(?:为|是|：|:)?(?:需求增加|正常|较高|较低|高|低)', '', text or '')
    fiber = r'膳食纤维|可溶性纤维|不可溶性纤维|不溶性纤维|菊粉|低聚果糖|'
    fiber += r'\b(?:dietary\s+fib(?:er|re)|soluble\s+fib(?:er|re)|insoluble\s+fib(?:er|re)|inulin|fructooligosaccharides?)\b'
    process = r'发酵|分解|代谢|利用|底物|产生|生成|吸水|粪便|排便|蠕动|饱腹|短链脂肪酸|'
    process += r'\b(?:ferment\w*|metaboli\w*|substrates?|produc\w*|SCFAs?|butyrate|propionate|bowel|motility|satiety)\b'
    return any(re.search(fiber, clause, re.I) and re.search(process, clause, re.I)
        for clause in re.split(r'[，,。；;！？\n]', tested))


def _health_process_duty_failures(line, target, source_quotes=None):
    duties = {
        'antiInflammatoryCapacity': (_anti_inflammatory_process_sentence, '肠道炎症的调节、限制或消退过程'),
        'oxidativeStressTolerance': (_oxidative_process_sentence, '氧化胁迫、耐氧或活性氧应答'),
        'gutImmunity': (_immune_process_sentence, '肠道免疫反应、免疫细胞或黏膜免疫调节'),
        'dietaryFiberNeed': (_fiber_process_sentence, '膳食纤维的发酵利用、排便或相关生理作用'),
    }
    for row in target.assessment_context:
        if row.get('semanticType') != 'healthSummary' or row.get('code') not in duties:
            continue
        predicate, process = duties[row['code']]
        if not predicate(line) or source_quotes is not None and not any(
                predicate(quote) for quote in source_quotes if isinstance(quote, str)):
            return [f'本栏须由实际采用的科学句及所选原文共同解释{process}；'
                '原状态标签、文献背景和邻近功能不能代替本句的同对象职责。没有适用句则保留空值，'
                '不补写其他机制或将候选相关性当作本栏已完成。']
    return []


def _functional_weak_state(target):
    if target.path[:2] != ('functionalPathways', 'pathways') or target.path[-1:] != ('healthMeaning',):
        return set(), False
    own = set(target.fact_ids)
    rows = [member for row in target.assessment_context
        for member in ([row, *row.get('members', [])] if isinstance(row, dict) else [])
        if isinstance(member, dict) and own.intersection(member.get('factIds') or ())]
    weak_ids = {fid for row in rows if str(row.get('sourceStatus') or '').strip() in LOW_FUNCTION_LEVELS
        or re.fullmatch(r'正常[-－—（(]弱[）)]?', str(row.get('sourceStatus') or '').strip())
        for fid in row.get('factIds', []) if fid in own}
    weak_domain = any(row.get('semanticType') == 'functionalStateScope'
        and row.get('assessmentLevel') in LOW_FUNCTION_LEVELS for row in rows)
    return weak_ids, weak_domain


def _functional_state_coverage_failures(line, target, linked=None, *, require_domain=False):
    """A true normal member cannot stand in for a weak domain's whole state."""
    weak_ids, weak_domain = _functional_weak_state(target)
    if not weak_ids and not weak_domain:
        return []
    own = set(target.fact_ids)
    aggregate = r'(?:整体|总体|整组|(?:本|该)(?:组|通路|功能域))[^，,。；;]{0,28}'
    praise = r'(?:保留(?:较好|良好)|表现(?:良好|平稳)|功能(?:正常|良好|平稳)|正常|均衡|优势)'
    claims = [match.group() for match in re.finditer(aggregate + praise, line)]
    claims = [claim for claim in claims if not re.search(r'(?:正常|强)(?:档)?(?:子项|项目|项|部分)', claim)]
    if not claims and not require_domain:
        return []
    represented = own if linked is None else {fact.fact_id for fact in linked}
    addresses = any(re.search(r'弱|偏低|低项|短板|不足|缺乏', clause)
        and not re.search(r'(?:没有|未见|无明显|无|并非|不是)[^，,。；;]{0,10}(?:弱|短板|不足|缺乏)', clause)
        for clause in re.split(r'[。；;！？\n]', line))
    if not addresses or not (represented & weak_ids or weak_domain and represented & own):
        return ['本功能域有已采用的弱/较弱状态或真实弱项，正常成员的独立解释不能替代整体判断。'
            '整体保留或正常的结论须同时回应本行真实弱项并绑定其依据；不按相对分值造弱项。']
    return []


def _health_meaning_scope_failures(line, target, review):
    if _functional_management_match(line, target):
        return []  # Management duty; the ordinary source/population reviews still apply.
    """Consume the existing object/scope proof against the actual health row."""
    role_failures = _measurement_meaning_role_failures(line, target, review)
    if _functional_meaning_review_context(target):
        if role_failures:
            return role_failures
        proof = review.get('meaningContribution')
        if proof is not None and (not isinstance(proof, dict) or proof.get('sameTargetObject') is not True
                or proof.get('contributionType') not in {'physiological_effect', 'health_impact'}):
            return ['引用句没有完成本通路实际对象的具体生理作用；同一篇文章的邻近功能或真实背景不能替代本栏。']
        return []
    if target.path[:2] != ('microbiomeAssessment', 'healthMetrics'):
        return role_failures
    summaries = [row for row in target.assessment_context if row.get('semanticType') == 'healthSummary']
    errors = [*role_failures, *_detected_gene_science_scope_failures(line, target), *_health_process_duty_failures(line, target)]
    if re.search(r'最重要(?:的)?因素|最大(?:的)?危险因素',line):
        errors.append('单项关联研究中的most significant表示统计关联显著，不能译为临床最重要或确定病因；保留研究人群与范围，用主要相关因素等忠实表述。')
    for row in summaries:
        producer_members = [member for context in target.assessment_context
            if context.get('semanticType') == 'healthStateSourceContext'
            and (context.get('aggregateState') or {}).get('code') == row.get('code')
            for member in context.get('memberStates', [])
            if set(member.get('factIds') or ()) <= set(target.fact_ids)]
        if row.get('code') == 'scfaProducerBacteria' and not _scfa_producer_science_scope(line, row, producer_members):
            errors.append('本栏对象是产短链脂肪酸菌，科学句须解释实际微生物生产/底物发酵过程或真实产菌成员作用；仅有丁酸等产物对宿主的抗炎、免疫效应不完成产菌职责，同篇邻句或名称中的产字不能代替。')
        if (row.get('code') in {'beneficialBacteria', 'pathogenicBacteria', 'opportunisticBacteria'}
                and re.search(r'饥饿|葡萄糖.{0,8}(?:耗尽|耗竭)|营养.{0,8}耗竭', line)
                and re.search(r'培养|存活|耐受|持留|休眠', line)):
            errors.append('培养底物耗竭时的存活现象不完成本栏实际菌群对人体健康的意义；须另选同对象适用的肠道作用原文。')
        if (row.get('code') in {'beneficialBacteria', 'opportunisticBacteria', 'pathogenicFungi'}
                and re.search(r'无菌小鼠|小鼠|大鼠|动物模型', line)
                and re.search(r'脑内|大脑|脑部|血脑屏障|中枢神经', line)):
            errors.append('动物脑部感染或实验结局不能替代本栏实际肠道成员的健康意义；另选与本类实际对象及肠道用途一致的原文。')
        if row.get('code') == 'beneficialBacteria' and re.search(r'胎盘|胎儿|母胎|母体适应', line):
            errors.append('母胎或胎盘发育结局不完成本栏肠道有益菌基础功能；保留小鼠限定也不能替代本栏用途。')
        if (row.get('code') == 'beneficialBacteria' and re.search(
                r'受到(?:研究)?关注|研究(?:关注|聚焦|热点|涉及|涵盖)|综述(?:聚焦|关注)|研究兴趣|'
                r'广泛(?:使用|应用)|免疫(?:调节)?特性[^，,。；;]{0,12}关注|具有.{0,8}免疫调节特性', line)
                and not re.search(r'产生|合成|分泌|降解|转化|发酵|交叉喂养|竞争排除|'
                    r'(?:增强|抑制|促进|降低|增加|维持|调节|上调|下调)[^，,。；;]{0,20}'
                    r'(?:肠上皮|屏障|紧密连接|定植|细胞因子|白介素|Treg|Th17|Th2|免疫应答)', line, re.I)):
            errors.append('研究关注、综述范围或笼统免疫调节特性属于研究背景，不能替代本栏具体生理作用；须选择实际成员或明示菌株的具体作用及结果原句。')
        if (row.get('code') == 'beneficialBacteria' and re.search(r'人乳|母乳|乳汁', line)
                and re.search(r'还原糖|酸化|代谢产出', line)
                and not re.search(r'肠道|肠上皮|屏障|定植|免疫|炎症|抑制.{0,6}(?:病原|致病)', line)):
            errors.append('人乳底物体外还原糖利用或酸化不能独立完成本栏肠道有益菌的生理作用或健康意义；选择与实际成员及肠道作用相符的原句。')
        if (row.get('code') == 'beneficialBacteria'
                and re.search(r'自闭|孤独症|母体免疫激活|抑郁模型|精神分裂|结膜|眼表', line)
                and re.search(r'模型|小鼠|大鼠|母体免疫激活|治疗|改善|修复|救援|缓解', line)):
            errors.append('特定疾病动物模型或眼表治疗作用不能承担本栏真实成员的肠道基础生理功能；保留小鼠限定仍不符合本栏用途，须另选同对象适用原文。')
        if row.get('code') in {'pathogenicBacteria', 'opportunisticBacteria'} and row.get('memberNames'):
            names = [alias.strip() for name in row['memberNames'] for alias in name.split(' / ')
                if len(alias.strip()) >= 2]
            if not any(name.casefold() in line.casefold() for name in names):
                errors.append('本栏已明确实际成员，健康意义须解释其中真实同一对象，不能用其他致病菌的泛综述替代。')
        if row.get('code') in {'pathogenicBacteria', 'opportunisticBacteria'}:
            # A measured species does not establish a particular clonal
            # lineage. Keep an independent basic species role instead of
            # assigning an unmeasured lineage's clinical cohort risk.
            names = [str(row.get('name') or ''), *row.get('memberNames', [])]
            for state in target.assessment_context:
                if state.get('semanticType') == 'healthStateSourceContext':
                    names.extend(str(member.get('name') or '') for member in state.get('memberStates', []))
            for match in re.finditer(r'(?<![A-Za-z0-9])((?:CC|ST)[- ]?\d+)\s*(?:谱系|克隆群|序列型)', line, re.I):
                lineage = match.group(1)
                if not any(re.search(r'(?<![A-Za-z0-9])' + re.escape(lineage) + r'(?![A-Za-z0-9])', name, re.I)
                        for name in names):
                    errors.append('本栏未提供该谱系或序列型的检测结果，不能用其特定队列风险替代已测成员的基本意义：' + lineage)
        if row.get('code') != 'opportunisticBacteria':
            continue
        if not re.search(r'机会致病|肠外|感染|脓肿|菌血症|败血|致病|坏死', line):
            errors.append('条件致病菌栏目须解释同一成员的一般机会致病作用或感染关联；仅保护免疫、屏障或定植抵抗不完成本栏职责。')
        details = str(row.get('details') or '')
        members = re.findall(r'(?:^|[；;])\s*([\u4e00-\u9fff]{2,18})(?=\s+[-+]?\d)', details)
        supplied = ' '.join(str(item.get(key) or '') for item in target.assessment_context
            for key in ('name', 'value', 'details'))
        for name in members:
            for match in re.finditer(r'([\u4e00-\u9fff]{1,6}型)' + re.escape(name), line):
                if match.group(0) not in supplied:
                    errors.append('本栏实际成员未提供原句作用所依赖的额外类型性状：' + match.group(0)
                        + '；研究中或动物限定不使该额外性状成为本栏对象，不作为健康意义。')
    population = (review.get('scope') or {}).get('population')
    gene_marker = _gene_marker_target(target)
    if not gene_marker:
        supplied = json.dumps(target.assessment_context, ensure_ascii=False)
        strains = re.findall(r'(?<![A-Za-z0-9])(?:ATCC(?:\s+PTA)?|DSM|IDCC)'
            r'\s*[-:]?\s*\d+(?![A-Za-z0-9])',
            line + ' ' + (population if isinstance(population, str) else ''), re.I)
        compact = lambda value: re.sub(r'[\s:-]', '', value).casefold()
        if any(compact(strain) not in compact(supplied) for strain in strains):
            errors.append('研究作用依赖特定菌株，而本模块只测得菌属/菌种或综合功能；'
                '未测菌株的试验结果不能充当该用户本项健康意义，应另选同一实际对象的基础作用原文。')
        exact_relation = any(row.get('semanticType') == 'approvedPersonalRelation'
            and row.get('text') == line for row in target.assessment_context)
        if not exact_relation and re.search(r'血管重塑|动脉重塑|烟雾病', line):
            errors.append('远端疾病研究中的血管重塑背景没有解释本模块实际菌群或肠道功能，'
                '须采用该真实对象的直接作用或已有个人关系，不能靠主题词重叠填充健康意义。')
    if gene_marker:
        actual_genes = {gene.casefold() for row in target.assessment_context
            for key in ('value', 'details')
            for group in re.findall(r'检出基因[：:]\s*([^；;\n]+)', str(row.get(key) or ''))
            for gene in re.split(r'[,，、\s]+', group)
            if re.fullmatch(r'[A-Za-z][A-Za-z0-9_-]*', gene)}
        for actor in re.findall(r'(?:^|[，,；;。])\s*([A-Za-z][A-Za-z0-9_-]*)'
                r'[^，,；;。]{0,20}?(?:编码|催化|参与|可与|通过)', line):
            if actual_genes and actor.casefold() not in actual_genes:
                errors.append('本栏实际基因的功能被其他未测对象作主语的调控链替代：' + actor
                    + '；应忠实说明已提供基因或对应蛋白本身的基本作用。')
        positions = [match.start() for gene in actual_genes for match in re.finditer(
            r'(?<![A-Za-z0-9_])' + re.escape(gene) + r'(?![A-Za-z0-9_])', line, re.I)]
        if positions and re.search(r'调控|控制|竞争|协同|破坏|增殖|定植', line[:min(positions)]):
            errors.append('首个实际基因出现前，句子已在解释其他主体的调控或感染过程；去掉编号不改变主语职责，应改写为实际基因/蛋白的基本作用。')
    animal = r'小鼠|大鼠|鼠模型|动物模型|\b(?:mouse|mice|murine|rat|rats)\b'
    if (not gene_marker and isinstance(population, str) and re.search(animal, population, re.I)
            and not re.search(animal, line, re.I)):
        errors.append('现有scope证明明确为动物研究，正文省略该研究范围；不以未明说人体为由放行，须整句忠实重写。')
    return errors


def _meaning_review_kind(review, target, line, *, cited, bound_ids):
    """Read a semantic duty verdict only after ordinary factual review passes."""
    if not _pure_science_review_path(target):
        return None
    proof = review.get('meaningContribution')
    if (cited and isinstance(proof, dict) and proof.get('contributionType') == 'management_direction'
            and proof.get('sameTargetObject') is True and review.get('claimRole') == 'management'
            and _functional_management_match(line, target, bound_ids if bound_ids else None)):
        return 'management_direction'
    if (not isinstance(proof, dict) or proof.get('sameTargetObject') is not True
            or _health_meaning_scope_failures(line, target, review)):
        return None
    kind = proof.get('contributionType')
    return kind if cited and kind in {'physiological_effect', 'health_impact'} and review.get('claimRole') not in {
        'source_fact', 'source_assessment', 'uncertainty'} else None


def _result_interpretation_lines(block, target):
    """Read private result/science receipts without granting review authority.

    Callers still validate the complete block against current facts and all
    original citations. An action, definition or measurement disclaimer alone
    never completes an explanation, even when its own review is valid.
    """
    if not isinstance(block, _ReviewedEvaluationBlock) or block._reviewed_path != target.path:
        return ()
    result = []
    for line, ids, cited, literal in block._sentence_sources:
        if (line not in block.text.splitlines() or not ids <= set(target.fact_ids)
                or (line, ids) in block._medical_advice_actions
                or _functional_management_match(line, target, ids)
                or re.search(r'^(?:建议|请|可(?:以)?(?:先|通过)|应(?:当)?(?:先|到|去|进行|增加|减少|保持|调整)|'
                    r'记录|保持|维持|调整|复查|就诊|随访|到[^，。]{0,12}(?:科|院))', line.strip())):
            continue
        if cited:
            refs = frozenset(int(number) for number, claims in block.evidence_claims.items()
                if line in claims.splitlines())
            if refs and refs <= set(block.evidence_refs) and any(
                    source_line == line and bound == ids and meaning_refs == refs
                    and kind in {'physiological_effect', 'health_impact'}
                    for source_line, kind, bound, meaning_refs in block._meaning_contributions):
                result.append(line)
            continue
        # Scope-only or definition-only sentences carry no patient result.
        # Literal observations and AI source assessments retain distinct
        # receipts; neither is reconstructed from public evidenceRefs.
        state_clause = any(re.search(r'异常|正常|偏高|偏低|升高|降低|丰富|稀少|阳性|阴性|检出|未检出|'
                r'强|弱|失调|失衡|差异|分布|保留|疑似|可能大|提示|已记录|已明确|已诊断|'
                r'耐药基因信号|非优先关注的保留项', clause)
            and not re.search(r'并非|不是|不能|无法|不代表|不等同|定义|总称|建议|应关注|应观察', clause)
            for clause in re.split(r'[，,；;。！？\n]', line))
        clinical_name = next((row.get('name') for row in target.assessment_context
            if row.get('semanticType') == 'medicalFindingScope'), None)
        if (clinical_name and clinical_name in line and re.search(r'记录|提示|自述|发现|存在|诊断|既往', line)
                and not re.search(r'是否|未见|没有|建议|应当', line)):
            state_clause = True
        clinical_observation_ids = {fid for row in target.assessment_context
            if row.get('semanticType') == 'sourceClinicalObservation' for fid in row.get('factIds', [])}
        if (ids & clinical_observation_ids and re.search(r'自述|检查|记录|症状|主诉|不适|本次|当前|已有|表现', line)
                and not re.search(r'建议|应当|请|复查|就诊', line)):
            state_clause = True
        if (ids and (literal or _assessment_proven(block, line, ids)) and state_clause
                and not re.search(r'(?:是|指|属于)[^。]{0,20}(?:总称|定义|一类物质)', line)):
            result.append(line)
    return tuple(dict.fromkeys(result))


def reviewed_result_lines(block, target, facts):
    """Return non-management explanation lines only after full live review."""
    return _result_interpretation_lines(block, target) if _reviewed_source_state(block, target, facts) else ()


def _health_meaning_complete(block, target):
    """Only live semantic responsibility proof can complete a health column."""
    if target.path[:2] == ('medicalAssessment', 'findings') and target.path[-1:] == ('sourceAdvice',):
        return bool(isinstance(block, _ReviewedEvaluationBlock)
            and block._reviewed_path == target.path and block._sentence_sources
            and all((line, ids) in block._medical_advice_actions
                for line, ids, _, _ in block._sentence_sources))
    if source_state_can_complete(target.path):
        results = _result_interpretation_lines(block, target)
        return bool(results and any(line in results and not cited
            and (literal or _assessment_proven(block, line, ids))
            for line, ids, cited, literal in block._sentence_sources))
    functional = target.path[:2] == ('functionalPathways', 'pathways') and target.path[-1:] == ('healthMeaning',)
    summary = (_functional_summary_path(target.path) or target.path ==
        ('nutritionAssessment', 'nutritionInterpretation', 'text'))
    medical = target.path == ('healthOverview', 'summaries', 'medical', 'text')
    if medical:
        if not isinstance(block, _ReviewedEvaluationBlock) or block._reviewed_path != target.path:
            return False
        # Clinical summaries reuse only the same patient's already approved
        # relation/plan, and still require the sentence's fresh citation review.
        # A marker/grade roster or unrelated general science cannot complete it.
        for line, ids, cited, literal in block._sentence_sources:
            if not cited or literal or _assessment_proven(block, line, ids):
                continue
            refs = {int(number) for number, claims in block.evidence_claims.items()
                if line in claims.splitlines()}
            if not refs or not refs <= set(block.evidence_refs):
                continue
            if any(row.get('semanticType') in {'approvedPersonalRelation', 'approvedManagementContext'}
                    and row.get('text') == line and row.get('factIds')
                    and set(row['factIds']) <= set(ids)
                    and set(row.get('evidenceRefs') or []) & refs
                    for row in target.assessment_context):
                return True
        return False
    if not health_amr_author_path(target.path) and not functional and not summary:
        return True
    if not isinstance(block, _ReviewedEvaluationBlock) or block._reviewed_path != target.path:
        return False
    metadata = {line: (ids, cited, literal) for line, ids, cited, literal in block._sentence_sources}
    if amr_interpretation_path(target.path) and any(
            ids and not cited and ids <= set(target.fact_ids)
            and _assessment_proven(block, line, ids)
            and re.search(r'关注|优先|保留项|保留记录', line)
            for line, (ids, cited, _) in metadata.items()):
        # A row's adopted state can support a reviewed priority judgement.
        # Broader mechanisms and drug susceptibility still require their own
        # applicable scientific evidence and both ordinary citation reviews.
        return True
    own = {fid for row in target.assessment_context if row.get('semanticType') == 'healthSummary'
        for fid in row.get('factIds', [])}
    if summary:
        own = {fid for row in _function_owner_observations(target) for fid in row.get('factIds', ())
            if fid in target.fact_ids}
        own.update(fid for row in target.assessment_context
            if row.get('semanticType') == 'nativeNutritionState' and row.get('sourceStatus')
            for fid in (row.get('aggregateFactIds') or row.get('factIds') or ())
            if fid in target.fact_ids)
    if functional:
        own = set(target.fact_ids)
    state_complete = not own or _program_source_state_target(target) or any(ids & own and not cited
        and _assessment_proven(block, line, ids) for line, (ids, cited, _) in metadata.items())
    if summary:
        state_complete = bool(own) and any(ids & own and not cited
            and _assessment_proven(block, line, ids) for line, (ids, cited, _) in metadata.items())
    if functional and not _program_source_state_target(target):
        weak_ids, weak_domain = _functional_weak_state(target)
        if weak_ids or weak_domain:
            state_complete = state_complete and any(not cited and ids & (weak_ids or own)
                and _assessment_proven(block, line, ids)
                and not _functional_state_coverage_failures(line, target, require_domain=True)
                for line, (ids, cited, _) in metadata.items())
    if not summary and state_complete and any(not cited and _assessment_proven(block, line, ids)
            and _personal_focus_binding(line, target, ids)
            for line, (ids, cited, _) in metadata.items()):
        # The independently source-reviewed state/priority role is useful
        # personal interpretation. It grants no physiological/causal proof.
        return True
    for line, kind, ids, refs in block._meaning_contributions:
        if line not in metadata or ids != metadata[line][0]:
            continue
        claimed = frozenset(int(number) for number, claims in block.evidence_claims.items()
            if line in claims.splitlines())
        if _health_process_duty_failures(line, target,
                [block.evidence_quotes.get(str(number), '') for number in refs]):
            continue
        if (kind in {'physiological_effect', 'health_impact', 'management_direction'}
                and (kind != 'management_direction' or _functional_management_match(line, target, ids))
                and metadata[line][1] and refs and refs == claimed
                and refs <= set(block.evidence_refs)):
            return state_complete
    return False


def _pure_science_review_path(target):
    """A real measured function may retain its independently reviewed biology.

    This changes neither the author protocol nor the patient's source result.
    A rejected neighbouring result sentence must not prevent a self-contained
    scientific sentence from receiving both ordinary original-text reviews.
    """
    return health_amr_author_path(target.path) or bool(
        _functional_meaning_review_context(target) and any(
            row.get('factIds') and row.get('name') and row.get('value') is not None
            for row in target.assessment_context))


def _pure_health_science_sentences(target, sentences):
    """One predicate serves syntax routing and the later semantic review."""
    return bool(_pure_science_review_path(target) and sentences
        and all(isinstance(item, dict) and isinstance(item.get('text'), str)
            and item['text'].strip() and item.get('evidenceRefs')
            and not re.search(r'本人|本例|本报告|本行|本项|该项|受检者|您的|你的|该患者|患者本人|'
                r'本次(?!研究|实验)|本组(?!研究|实验)|本样本|该样本|本标本|'
                r'(?:检测|测得|检出|测量|评估)(?:结果|值|显示|为|呈)|'
                r'(?:原|来源)(?:报告|标记|标签)|药敏(?:结果|显示|为)', item['text'])
            and not _needs_source_absence_check(item['text']) for item in sentences))


def _pure_health_science_review(block, target, sentences):
    """Empty IDs alone never erase a statement about this patient's results."""
    return not block.fact_ids and _pure_health_science_sentences(target, sentences)


def _health_science_target_vocabulary(target, facts):
    """Actual target/member words, without patient measurements or identities."""
    genes = []
    allowed = ({fid for row in _function_owner_observations(target) for fid in row['factIds']}
        if independent_function_author_path(target.path) else set(target.fact_ids))
    for fid in target.fact_ids:
        fact = facts.get(fid)
        if fact is not None and fid in allowed:
            genes.extend(gene for group in re.findall(r'检出基因[：:]\s*([^；;\n]+)', fact.value)
                for gene in re.split(r'[,，、\s]+', group) if re.fullmatch(r'[A-Za-z][A-Za-z0-9_-]*', gene))
    summaries = [row for row in target.assessment_context if row.get('semanticType') == 'healthSummary']
    members = [member for row in target.assessment_context
        if row.get('semanticType') == 'healthStateSourceContext' for member in row.get('memberStates', [])]
    return {'sourceNames': list(dict.fromkeys([*_scientific_source_names(target, facts),
            *(name for row in summaries for name in row.get('memberScientificNames', []))])),
        'measurementCodes': [row.get('code') for row in summaries],
        'memberStates': [{'name': member['name'], 'sourceStatus': member.get('sourceStatus')}
            for member in members if isinstance(member.get('name'), str)],
        'geneSymbols': list(dict.fromkeys(genes)),
        'resultKinds': list(dict.fromkeys(row['resultKind'] for row in target.assessment_context
            if isinstance(row.get('resultKind'), str)))}


