def _review_schema(*, health_meaning=False) -> dict:
    return {'items': [{'id': '输入id', 'valid': True, 'supportQuoteIds': [],
        'unsupportedClaims': [], 'applicability': 'applicable|general|not_applicable|unknown',
        'clinicalRelevance': 'direct|general|unrelated',
        'claimRole': 'etiology|mechanism|outcome|management|background|source_fact|source_assessment|uncertainty',
        'clinicalFocusCoverage': [{'code': '本句实际回应的selectedClinicalFocus.code', 'conveyed': True}],
        'sourceAbsenceCheck': {'inventoryChecked': True,
            'verdict': 'absent|historical_only|partial_information|contradicted|not_source_claim',
            'matches': [{'factId': '真实来源ID', 'factQuote': '来源逐字原文'}], 'reason': '核对理由'},
        'scope': {'population': '实际研究人群或无研究人群',
            'requirements': [{'condition': '实际适用前提', 'evidenceQuoteId': '当前quoteOptions编号或空字符串',
                'factId': '真实来源ID', 'factQuote': '逐字原文',
                'useAs': 'clinical_record|patient_report|microbiome_result|source_model_result|source_context|subject_attribute',
                'purpose': 'description|eligibility|clinical_action|microbiome_action'}],
            'premiseMatches': [{'premiseId': '本item.evidence.scopeOptions的每个实际ID',
                'sourceQuote': '对应scopeOptions原句', 'result': 'met|not_applicable|context_preserved',
                'factIds': ['实际同问题来源ID'], 'factQuotes': {'实际ID': '同ID原value逐字片段'}}],
            'missing': [], 'adviceKind': 'explanation|general_care|referral_or_test|specific_nutrient|drug_or_procedure'},
        **({'meaningContribution': _meaning_review_schema()} if health_meaning else {}),
        'reason': '具体理由'}]}


def _normalize_draft_citation_numbers(raw, allowed_refs):
    """Normalize only known canonical number strings in an internal draft.

    This is syntax compatibility, not reference selection or approval. The
    original model packet, sentence text, fact IDs and quotations stay whole.
    """
    result = deepcopy(raw)
    known = {str(number): number for number in allowed_refs if type(number) is int and number > 0}
    failures = []

    def normalize(owner):
        if not isinstance(owner, dict) or 'evidenceRefs' not in owner:
            return
        refs = owner['evidenceRefs']
        if not isinstance(refs, list):
            failures.append('evidenceRefs须为本节点已提供文献编号的整数数组')
            return
        refs = [known.get(number, number) if isinstance(number, str) else number for number in refs]
        owner['evidenceRefs'] = refs
        if any(type(number) is not int or number not in allowed_refs for number in refs):
            failures.append('evidenceRefs含非规范编号或本节点未提供的引用，不能推测或新增文献')
        elif len(refs) != len(set(refs)):
            failures.append('同一evidenceRefs数组包含重复编号，不能去重后自动通过')

    normalize(result)
    if isinstance(result.get('sentences'), list):
        for sentence in result['sentences']:
            normalize(sentence)
    return result, list(dict.fromkeys(failures))


