def _amr_state_source_draft(target, facts):
    """Propose one missing row judgement, never an automatic acceptance.

    Only a literal adopted AMR state and its own unchanged observations may
    supply this proposal. Its syntax, scope and independent source review are
    still performed by the ordinary composition pipeline.
    """
    if not amr_interpretation_path(target.path):
        return None
    rows = [row for row in target.assessment_context
        if row.get('semanticType') == 'antimicrobialResistance']
    if len(rows) != 1:
        return None
    row = rows[0]
    judgments = {'正常': '本次评估中非优先关注的保留项',
        '注意': '本次评估中需关注的耐药基因信号',
        '耐药': '本次评估中需优先关注的耐药基因信号'}
    label, name = row.get('sourceStatus'), row.get('name')
    ids = tuple(dict.fromkeys(row.get('factIds') or ()))
    if (label not in judgments or not isinstance(name, str) or not name.strip()
            or row.get('value') in (None, '') or not ids or not set(ids) <= set(target.fact_ids)
            or any(fid not in facts or facts[fid].kind != 'function'
                or facts[fid].status != label
                or facts[fid].value.strip() != str(row['value']).strip() for fid in ids)):
        return None
    text = name.strip() + '耐药基因为' + judgments[label] + '。'
    return {'code': target.code, 'state': 'ready', 'factIds': list(ids),
        'sentences': [{'text': text, 'evidenceRefs': []}]}


