def _health_production_author_fields(target, facts, plan):
    """Use an actual producer-process quote without copying an old meaning."""
    producer = any(row.get('semanticType') == 'healthSummary' and row.get('code') == 'scfaProducerBacteria'
        for row in target.assessment_context)
    candidates = (plan or {}).get('productionOriginalSentenceCandidates') or []
    if not producer or not candidates:
        return {}
    return {'preferredOriginalSentence': deepcopy(candidates[0]),
        'purpose': _health_author_responsibility(target, facts),
        'productionReferenceInstruction': plan['productionInstruction']
            + '若原句同时带下游免疫效应，本栏只选择其中可独立支持的微生物发酵/生成过程，'
              '忠实另写一句并保留实际研究范围；完整原文仍供双审。'
              '不把下游T细胞或补充干预结局复述为生产菌职责。'}


def _health_immune_author_fields(target, facts, plan):
    """Offer an actual immune process with its original experimental scope."""
    immune = any(row.get('semanticType') == 'healthSummary' and row.get('code') == 'gutImmunity'
        for row in target.assessment_context)
    candidates = (plan or {}).get('immuneOriginalSentenceCandidates') or []
    if not immune or not candidates:
        return {}
    return {'preferredOriginalSentence': deepcopy(candidates[0]),
        'purpose': _health_author_responsibility(target, facts),
        'immuneFunctionReferenceInstruction': plan['immuneFunctionInstruction']}


def _function_science_author_target(target):
    """Keep pure science only where no source-interpretation role is requested."""
    return (independent_function_author_path(target.path) and bool(_function_owner_observations(target))
        and not any(row.get('semanticType') in {'approvedFunctionalManagementContext',
            'approvedPersonalFocus', 'approvedPersonalRelation'} for row in target.assessment_context)
        and not _individual_function_target(target))


