def _function_science_author_fields(target, facts, plan=None):
    """Offer actual names/original handles, never patient values or old prose."""
    if not independent_function_author_path(target.path) or not _function_owner_observations(target):
        return {}
    measured_names = _function_owner_names(target)
    if not _function_science_author_target(target):
        member_states = [{key: deepcopy(row.get(key)) for key in (
            'name', 'factIds', 'sourceStatus', 'assessmentLevel', 'referenceRange')}
            for row in _function_owner_observations(target)]
        management_sentences = [{key: deepcopy(row.get(key)) for key in ('text', 'factIds', 'evidenceRefs')}
            for row in target.assessment_context
            if row.get('semanticType') == 'approvedFunctionalManagementContext'
            and isinstance(row.get('text'), str) and row['text'].strip()
            and row.get('factIds') and set(row['factIds']) <= set(target.fact_ids)
            and row.get('evidenceRefs') and all(type(number) is int and number > 0
                for number in row['evidenceRefs'])]
        personal_ids = sorted({fid for context in target.assessment_context
            if context.get('semanticType') in {'functionPersonalContext', 'functionPlanningContext',
                'approvedPersonalFocus'} for fid in context.get('factIds', ())
            if fid in target.fact_ids and fid in facts and facts[fid].kind in {'clinical', 'self_reported'}})
        fields = {'functionScienceOnly': False,
            'purpose': target.purpose + ' ' + _FUNCTION_INTERPRETATION_AUTHOR_RESPONSIBILITY,
            'contentResponsibility': _FUNCTION_INTERPRETATION_AUTHOR_RESPONSIBILITY,
            'targetVocabulary': {'sourceNames': list(dict.fromkeys(measured_names))},
            'sourceInterpretationResponsibility': '先用本组真实已采用状态说明局部短板、保留表现或关注方向，'
                'evidenceRefs=[]并独立来源审核；再另句说明本组同一实测对象的适用科学意义并接受原文双审。'
                '有支持时说明本次实际弱项与健康风险的联系，并结合本target同主题真实背景。'
                '不复制结果名册，不把科学句当本人临床状态，缺少科学原句不影响保留已审状态判断。'}
        if plan and plan.get('originalSentenceCandidates'):
            fields['healthFunctionReferencePlan'] = {'kind': plan.get('kind'),
                'sourceMemberNames': deepcopy(plan.get('sourceMemberNames', [])),
                'originalSentenceCandidates': deepcopy(plan['originalSentenceCandidates'][:4]),
                'preferredNumbers': list(dict.fromkeys(row['number']
                    for row in plan['originalSentenceCandidates'][:4])),
                'instruction': '候选仅帮助定位同主题实际原文，不是批准，也不强制翻译第一条定义。'
                    '可用完整原文实际支持的健康影响解释真实弱项；没有正面依据不补个人连接。'}
        if target.path == ('nutritionAssessment', 'nutritionInterpretation', 'text'):
            from modules.report.evaluation_synthesis import nutrition_intro_author_fields
            if frame := nutrition_intro_author_fields(target.assessment_context, facts):
                fields.update(frame)
                fields['healthFunctionReferencePlan'] = None
                fields['preferredOriginalSentence'] = None
        # Dedicated nutrition/science views are author hints, not authority
        # to discard the live same-behaviour plans or patient scope selected
        # by this exact target. All sentences keep their original reviews.
        fields.update(functionScienceOnly=False,
            purpose=_FUNCTION_INTERPRETATION_AUTHOR_RESPONSIBILITY,
            contentResponsibility=_FUNCTION_INTERPRETATION_AUTHOR_RESPONSIBILITY,
            allowedFactIds=list(target.fact_ids), sourceAssessmentAllowed=_source_assessment_path(target.path),
            assessmentContext=deepcopy(list(target.assessment_context)),
            measuredMemberStateAudit=member_states,
            reusableManagementSentences=management_sentences,
            independentSentenceMaterials={
                'measuredMemberFactIds': sorted({fid for row in member_states for fid in row.get('factIds') or ()}),
                'observedPersonalFactIds': personal_ids,
                'approvedSameMemberRelationships': [deepcopy(row) for row in target.assessment_context
                    if row.get('semanticType') == 'approvedPersonalRelation'],
                'personalMaterialUse': '个人事实是当前症状、病史或生活背景，不能只凭同现就说它造成该功能变化；'
                    '有同成员已审关系才写功能与具体风险的医学联系，日常改善只采用reusableManagementSentences。'
                    '源状态句只绑定本句实际成员；独立科学句只引用实际支持它的原文；'
                    '个人规划句采用原行动全部factIds及evidenceRefs，不让三类内容共用一个功能组ID或一篇不相符的文献。'},
            managementSentenceInstruction='reusableManagementSentences只作为同一行为原计划的写作材料，不是本轮免审批准。'
                '确有需要采用时逐字复制一条完整text及其全部factIds、evidenceRefs作为独立sentence item；'
                '不要加可等前缀、不换食品对象、频次或用途、不丢临床适用事实和引文，不借功能组ID代替行为事实。'
                '同一计划已有其他段落完整展示时不反复复写；新效益、其他管理或对功能分值的改善另需独立适用证据。',
            memberStateAuditInstruction='此账本仅供写作核对，不是正文。sourceStatus与assessmentLevel保留自身实际原词，'
                '空值表示本项未携带该信息，不能用同组或其他子项的等级补齐。'
                '组级原始方向和细项能力分档分别核对，不从较弱猜下降，也不从合成能力强推断有益。'
                '写多数、普遍、全部、最高或最低前须逐项核对本对象完整成员，'
                '不把有害代谢物的无原级记录写成未升高、正常或不利短板；正文不解释这些核对方法。',
            sourceInterpretationResponsibility='源内判断、适用科学解释与已审真实行为管理是独立职责。'
                '三类职责分为独立sentence item，逐句填各自factIds与实际evidenceRefs，不以一个功能组ID支持后半句生活方式命令。'
                '仅写有实际依据的部分，不能以状态复述或孤立科普代替个体解读；科学句引用同对象原文，'
                '同主题真实个人关注句采用本target已提供的A/B/C事实，不把一般生理作用声称为本人的病因。'
                '管理句仅完整采用approvedFunctionalManagementContext的同真实行为行动并独立双审。'
                '不把医学状态当管理批准，不声称行为导致或必定提高本功能分值。'
                '必要测量边界只说明本项真实测量类型，不附加疾病排除、内部评级规则或资料审计文案；'
                '某类支持为空时省略该类句，保留其他独立通过的有用判断。')
        return fields
    result = {'functionScienceOnly': True, 'purpose': _FUNCTION_SCIENCE_AUTHOR_RESPONSIBILITY,
        'contentResponsibility': _FUNCTION_SCIENCE_AUTHOR_RESPONSIBILITY,
        'allowedFactIds': [], 'sourceAssessmentAllowed': False,
        'assessmentContext': [],
        'targetVocabulary': {'sourceNames': list(dict.fromkeys(measured_names))}}
    if plan and plan.get('kind') in {'amino_acid_function', 'neurotransmitter_function',
            'measured_sugar_function', 'measured_metabolite_function'} \
            and plan.get('originalSentenceCandidates'):
        first = deepcopy(plan['originalSentenceCandidates'][0])
        result['preferredOriginalSentence'] = first
        result['healthFunctionReferencePlan'] = {
            'kind': plan['kind'], 'sourceMemberNames': deepcopy(plan.get('sourceMemberNames', [])),
            'originalSentenceCandidates': [first], 'preferredNumbers': [first['number']],
            'instruction': (plan['instruction'] if plan['kind'] in {'neurotransmitter_function',
                'measured_sugar_function', 'measured_metabolite_function'} else
                '仅忠实译述第一条候选中独立支持的一项生理作用；不融合其他原句或下游产物作用。'
                '保留完整原文中的实际范围限定，照常接受原文及选定引句两轮独立审核。')}
        if plan['kind'] == 'neurotransmitter_function':
            result['subjectSelectionInstruction'] = plan['instruction']
    return result


def _favorable_author_fields(target, facts):
    """Narrow only the author's packet; guards keep the complete inventory."""
    if target.path != ('comprehensiveConclusion', 'favorableFactors', 'text'):
        return {}
    directed = {fid for row in target.assessment_context if row.get('semanticType') == 'nativeNutritionState'
        for member in row.get('members', []) if member.get('direction') in {'up', 'down'}
        for fid in member.get('factIds', [])}
    normal = {'正常', '平衡', '强', '合成能力强', '阴性', '未见异常'}
    observations, ids = [], set()
    for row in _function_owner_observations(target):
        own = set(row['factIds']).intersection(target.fact_ids)
        if ((row.get('assessmentLevel') or row.get('sourceStatus')) not in normal
                or own.intersection(directed) or any(facts[fid].abnormal for fid in own if fid in facts)):
            continue
        own.intersection_update(facts)
        if own:
            observation = {**deepcopy(row), 'factIds': sorted(own)}
            processes = [member for context in target.assessment_context
                if context.get('semanticType') == 'nativeNutritionState'
                for member in context.get('members', [])
                if member.get('name') == row.get('name')
                and own.intersection(member.get('factIds', []))]
            if (processes and len({member.get('processType') for member in processes}) == 1
                    and processes[0].get('processType') in {'合成', '分解'}):
                observation.update(processType=processes[0]['processType'],
                    processOrigin=processes[0].get('processOrigin'))
            observations.append(observation)
            ids.update(own)
    # Clinical normal records remain eligible without acquiring native group
    # abnormalities or weak nutrient members that were added only for review.
    ids.update(fid for fid in target.fact_ids if fid in facts and facts[fid].kind == 'clinical'
        and facts[fid].status in normal and not facts[fid].abnormal and fid not in directed
        and not _outside_printed_reference(facts[fid].value, facts[fid].reference_range, facts[fid].unit))
    for row in target.assessment_context:
        if row.get('semanticType') != 'nativeFunctionType' or not ids.intersection(row.get('memberFactIds', [])):
            continue
        type_ids = [fid for fid in row.get('typeFactIds', []) if fid in facts and fid in target.fact_ids]
        observations.append({**deepcopy(row), 'memberFactIds': sorted(ids.intersection(row['memberFactIds'])),
            'typeFactIds': type_ids})
        ids.update(type_ids)
    return {'allowedFactIds': [fid for fid in target.fact_ids if fid in ids],
        'assessmentContext': observations,
        'sourceAssessmentInstructions': '仅归纳allowedFactIds中实际正常或有利的独立保留项；'
            '本节点不生成弱项、全组异常、管理顺序或评级方法。按同一成员已提供的真实合成/分解类型表述，'
            '所有句子evidenceRefs=[]，逐句绑定实际使用的来源；没有真实保留项时返回insufficient。'}


def _exposure_author_target(target):
    return (target.path[:2] == ('medicalAssessment', 'triggerAnalysis')
        and any(row.get('semanticType') == 'triggerScope' and row.get('code') == 'exposures'
            for row in target.assessment_context))


def _exposure_modifiability_repair_fields(target, previous, facts):
    """Request one missing grade without lending it symptoms or old proof.

    The retained association/strength must already have live source review.
    This returns author context only, never a grade or a reviewed block; the
    new proposal still uses the ordinary source review and full-row merger.
    """
    if (not _exposure_author_target(target) or previous is None
            or not _reviewed_source_state(previous, target, facts)):
        return None
    columns = _trigger_columns(previous.text, allow_fact_only=True) or {}
    if (not columns.get('association') or not columns.get('evidenceStrength')
            or columns.get('modifiability')):
        return None
    scope = next(row for row in target.assessment_context if row.get('semanticType') == 'triggerScope')
    own = [fid for fid in target.fact_ids if fid in scope.get('factIds', []) and fid in facts]
    known = [fid for fid in own if any(clause.strip() and not re.search(
        r'不清楚|不知道|不详|未知|未回答|未提供|未询问|未记录', clause)
        for clause in re.split(r'[，,。；;\n]', facts[fid].value or ''))]
    if not known:
        return None
    return {'allowedFactIds': own,
        'assessmentContext': [{**deepcopy(scope), 'factIds': own, 'patientStateFactIds': []}],
        'purpose': '仅为当前烟酒/环境行提出尚缺的可干预性等级；只使用本行真实行为。'
            '已审关联和证据强度由程序原样保留，不重写，不用症状或疾病作可改变性的依据。'
            'code必须逐字使用本请求的code，不改为modifiability路径。',
        'triggerRepair': {'retainedColumns': columns, 'requestedColumns': ['可干预性'],
            'instruction': '只返回一个sentence item，text为可干预性：后接高/中/低/维持/—之一，'
                'evidenceRefs=[]，state=insufficient；factIds只绑定本行实际使用的行为来源。'
                '不改关联或证据强度，不补频次、容量、医学安全结论或任何诊疗建议。'},
        'exposureModifiabilityRepair': {
            'retainedAssociation': columns['association'],
            'instruction': '依据已审关联与本行实际行为评判可干预性，不能仅因理论上可改变就判高。'
                '已审关联未识别需改变的问题且有真实保护习惯时，可评维持；'
                '这只维持已确认的保护习惯，不表示饮酒有益、少量安全或无需评估。'
                '实际明确不良行为可评高；中须真实外部或医师约束，只有未知信息可留空。'
                '本字段仅是新模型提案任务，未授予任何已审核证明。'},
        'availableEvidenceNumbers': []}


def _medication_author_target(target):
    return (target.path[:2] == ('medicalAssessment', 'triggerAnalysis')
        and any(row.get('semanticType') == 'triggerScope' and row.get('code') == 'medications'
            for row in target.assessment_context))


def _medication_category_mentions(target, facts):
    own = {fid for row in target.assessment_context if row.get('semanticType') == 'triggerScope'
        for fid in row.get('factIds', [])}
    mentions = [(fid, match.group()) for fid in target.fact_ids
        if fid in own and fid in facts for match in re.finditer(
            r'(?:通便|润肠|泻下|降压|降糖|抗感染|抗炎|镇痛|助眠)(?:相关|类)?(?:药物|药品|用药|药)',
            facts[fid].value)]
    return [{'factId': fid, 'literalCategory': text} for fid, text in dict.fromkeys(mentions)]


def _medication_association_source_draft(target, previous, facts):
    """Propose a bounded missing association; independent review still owns it.

    An existing, reviewed weak judgement is required. The proposal only names
    an explicitly supplied medicine category and affirmative self-reported
    symptoms; it supplies no mechanism, indication, benefit or new grade.
    """
    if (not _medication_author_target(target) or previous is None
            or not _reviewed_source_state(previous, target, facts)):
        return None
    columns = _trigger_columns(previous.text, allow_fact_only=True) or {}
    if columns.get('association') or not re.fullmatch(r'弱[。.]?', (columns.get('evidenceStrength') or '').strip()):
        return None
    scope = next(row for row in target.assessment_context if row.get('semanticType') == 'triggerScope')
    mentions = [row for row in _medication_category_mentions(target, facts)
        if row['factId'] in facts and any(row['literalCategory'] in clause
            and not re.search(r'没有|未|否认|不清楚|未知|不详|停止|停用|\b(?:no|not|unknown)\b', clause, re.I)
            for clause in re.split(r'[，,。；;\n]', facts[row['factId']].value))]
    if not mentions:
        return None
    symptoms = []
    for fid in scope.get('patientStateFactIds', []):
        fact = facts.get(fid)
        if (fact is None or fact.kind != 'self_reported' or not fact.source.startswith('用户自述：')
                or not 1 < len(fact.name) <= 20 or re.search(r'[，,。；;\n]|没有|否认|未|不清楚|未知|不详', fact.name)):
            continue
        answer = fact.value.split('回答：', 1)[-1]
        if any(fact.name in clause and not re.search(r'没有|否认|未|不清楚|未知|不详|\b(?:no|not|unknown)\b', clause, re.I)
                for clause in re.split(r'[，,。；;\n]', answer)):
            symptoms.append((answer.find(fact.name), fact))
    symptoms.sort(key=lambda row: (row[0], row[1].fact_id))
    selected = []
    for _, fact in symptoms:
        if not any(fact.name == other.name for other in selected):
            selected.append(fact)
        if len(selected) == 3:
            break
    if not selected:
        return None
    medicine = mentions[0]
    text = ('关联分析：原报告记载' + medicine['literalCategory'] + '用药记录，与本人自述的'
        + '、'.join(fact.name for fact in selected)
        + '共同存在，本次将用药背景与这些不适列为弱线索的候选关注方向。')
    return {'code': target.code, 'state': 'insufficient',
        'factIds': [medicine['factId'], *(fact.fact_id for fact in selected)],
        'sentences': [{'text': text, 'evidenceRefs': []}]}


def _trigger_source_state_draft(target, previous, facts):
    """Propose one missing personal focus; a fresh row review owns approval.

    Failed paper explanations do not erase usable behaviour/state inputs.
    This proposal adds no mechanism, treatment benefit or disease diagnosis;
    it cannot be published without the ordinary complete-row source review.
    """
    if target.path[:2] != ('medicalAssessment', 'triggerAnalysis'):
        return None
    columns = _trigger_columns(previous.text, allow_fact_only=True) if previous else None
    if columns and all(columns.values()) and _reviewed_source_state(previous, target, facts):
        return None
    scope = next((row for row in target.assessment_context
        if row.get('semanticType') == 'triggerScope'), {})
    code = scope.get('code')
    if code not in {'diet', 'exercise', 'sleep'}:
        return None
    own = [facts[fid] for fid in scope.get('factIds', []) if fid in facts
        and fid in target.fact_ids and facts[fid].kind == 'self_reported'
        and facts[fid].value.strip() and not re.fullmatch(
            r'不清楚|不知道|不详|未知|未回答|未提供|0|false', facts[fid].value.strip(), re.I)]
    states = [facts[fid] for fid in scope.get('patientStateFactIds', []) if fid in facts
        and fid in target.fact_ids and facts[fid].kind in {'clinical', 'self_reported'}
        and (facts[fid].kind != 'clinical' or facts[fid].abnormal
            or facts[fid].status in {'偏高', '偏低', '异常', '阳性'})]
    if not own or not states:
        return None
    # These are symptom/result topics already present, never added diagnoses.
    themes = ((r'便秘|硬便|(?:粪便|大便|便便).{0,8}(?:硬|干)|排便.{0,8}(?:费力|困难|不尽|用力)', '排便困难'),
        (r'反酸|烧心', '反酸或烧心不适'), (r'腹胀', '腹胀'),
        (r'疲倦|疲劳|乏力', '疲倦或乏力'), (r'入睡困难|失眠|睡眠困难', '睡眠不适'),
        (r'血糖|糖化血红蛋白', '血糖异常'), (r'血脂|甘油三酯|胆固醇', '血脂异常'),
        (r'腰围|体重指数|超重|肥胖', '体型相关异常'))
    selected = next(((label, [fact for fact in states if any(
        re.search(pattern, clause) and not re.search(
            r'无|否认|没有|未出现|不伴|不存在|正常|阴性', clause)
        for clause in re.split(r'[，,。；;\n]', fact.value))])
        for pattern, label in themes if any(re.search(pattern, fact.name + ' ' + fact.value)
            for fact in states)), None)
    if selected is None or not selected[1]:
        return None
    label, relevant = selected
    ceiling = _trigger_strength_ceiling(target, facts)
    if ceiling['maxLevel'] == '不足':
        return None
    matched = set(ceiling.get('matchingBehaviourFactIds', []))
    constraint_ids = []
    if matched:
        own = [fact for fact in own if fact.fact_id in matched]
        if not own:
            return None
        content = ' '.join(fact.value for fact in own)
        if code == 'diet':
            labels = [name for pattern, name in ((r'蔬菜|水果|全谷|杂粮|豆类|膳食纤维', '膳食纤维来源的饮食结构'),
                (r'饮水|白水|喝水', '饮水习惯'), (r'晚餐|夜宵|外卖|外食|早餐', '进食节律'))
                if re.search(pattern, content)]
        elif code == 'exercise':
            labels = [name for pattern, name in ((r'久坐|连续坐', '久坐习惯'),
                (r'运动|锻炼|快走|步行|活动|散步', '身体活动')) if re.search(pattern, content)]
        else:
            labels = [name for pattern, name in ((r'熬夜|晚睡|不规律', '作息节律'),
                (r'手机|屏幕', '睡前屏幕使用')) if re.search(pattern, content)]
        if not labels:
            return None
        text = label + '的行为相关关注包括' + '、'.join(labels) + '。'
        strength, modifiable = ceiling.get('recommendedLevel') or ceiling['maxLevel'], '高'
        from modules.report.evaluation_priority import trigger_modifiability_constraint_failures
        for fid in [*scope.get('factIds', []), *scope.get('patientStateFactIds', [])]:
            if fid not in target.fact_ids or fid not in facts:
                continue
            own_constraint = fid in scope.get('factIds', [])
            if not trigger_modifiability_constraint_failures('中', scope={**scope,
                    'factIds': [fid] if own_constraint else [],
                    'patientStateFactIds': [] if own_constraint else [fid]}, facts=facts):
                constraint_ids.append(fid)
        if constraint_ids:
            modifiable = '中'
    elif code == 'sleep':
        # A clock record supplies neither a sleep disorder nor its cause.
        # Do not turn an unclassified schedule into a behavioural problem.
        if _trigger_sleep_clock_only(target, facts):
            return None
        return None  # No adopted relationship is an internal gap, not prose.
    else:
        return None
    own_ids = list(dict.fromkeys(fact.fact_id for fact in own))
    ids = list(dict.fromkeys([*own_ids, *(fact.fact_id for fact in relevant)]))
    modifiable_ids = list(dict.fromkeys([*own_ids, *constraint_ids]))
    return {'code': target.code, 'state': 'ready',
        'factIds': list(dict.fromkeys([*ids, *modifiable_ids])),
        'sentences': [{'text': '关联分析：' + text, 'factIds': ids, 'evidenceRefs': []},
            {'text': '证据强度：' + strength, 'factIds': ids, 'evidenceRefs': []},
            {'text': '可干预性：' + modifiable, 'factIds': modifiable_ids, 'evidenceRefs': []}]}


